layer.onloaded:
js(
      fetch('https://eldorado775.github.io/m/sports.html')
        .then(function(response) {
          alert('status=' + response.status + ', type=' + response.type);
          return response.text();
        })
        .then(function(html) {
          alert('length=' + html.length);
          console.log(html.substring(0, 500));
        })
        .catch(function(error) {
          alert('FETCH ERROR: ' + error);
          console.error(error);
        });
    );
